            if (!decode_rle(entries[i].data, entries[i].original_size, decoded)) {
                std::fprintf(stderr, "invalid RLE data for '%s'\n",
                             entries[i].name.c_str());
                return 3;
            }
            entries[i].data.swap(decoded);
        }
    }

    // Validation passed: now create the output tree.
    fs::path outdir = argv[2];
    fs::create_directories(outdir);
    for (const Entry& e : entries) {
        fs::path p = outdir / e.name;
        fs::create_directories(p.parent_path());
        std::ofstream out(p, std::ios::binary | std::ios::trunc);
        if (!out) {
            std::fprintf(stderr, "cannot write '%s'\n", p.string().c_str());
            return 3;
        }
        out.write(e.data.data(), e.data.size());
        if (!out) {
            std::fprintf(stderr, "write failed for '%s'\n", p.string().c_str());
            return 3;
        }
    }
    return 0;
}

// unpack <archive> <outdir> -- PAK1 archive unpacker (C++17, standard library only)
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <filesystem>
#include <string>
#include <vector>

namespace fs = std::filesystem;

struct Entry {
    std::string name;
    uint8_t method;          // 0 = stored, 1 = RLE
    uint32_t stored_size;
    uint32_t original_size;
    std::vector<char> data;  // raw stored bytes
};

// ---------------------------------------------------------------- name safety
static bool name_safe(const std::string& name) {
    if (name.empty()) return false;
    if (name.front() == '/') return false; // absolute path
    size_t i = 0;
    while (i < name.size()) {
        size_t j = name.find('/', i);
        if (j == std::string::npos) j = name.size();
        std::string comp = name.substr(i, j - i);
        if (comp.empty() || comp == "." || comp == "..") return false;
        for (char c : comp) {
            if (c == '\\' || c == ':') return false;
        }
        i = j + 1;
    }
    return true;
}

// ---------------------------------------------------------------- archive parse
static bool parse_archive(const std::vector<char>& buf, std::vector<Entry>& entries) {
    const size_t n = buf.size();
    if (n < 8) return false;
    if (std::memcmp(buf.data(), "PAK1", 4) != 0) return false;

    uint32_t count = (uint32_t)buf[4]
                   | ((uint32_t)buf[5] << 8)
                   | ((uint32_t)buf[6] << 16)
                   | ((uint32_t)buf[7] << 24);

    if (count > (n - 8) / 11) return false;

    size_t off = 8;
    entries.reserve(count);
    for (uint32_t i = 0; i < count; ++i) {
        if (off + 11 > n) return false;
        uint16_t name_len = (uint16_t)buf[off]
                          | ((uint16_t)buf[off + 1] << 8);
        off += 2;
        if (off + (size_t)name_len + 9 > n) return false;
        std::string name(buf.begin() + off, buf.begin() + off + name_len);
        off += name_len;
        uint8_t method = buf[off];
        off += 1;
        uint32_t stored_size = (uint32_t)buf[off]
                             | ((uint32_t)buf[off + 1] << 8)
                             | ((uint32_t)buf[off + 2] << 16)
                             | ((uint32_t)buf[off + 3] << 24);
        off += 4;
        uint32_t original_size = (uint32_t)buf[off]
                                | ((uint32_t)buf[off + 1] << 8)
                                | ((uint32_t)buf[off + 2] << 16)
                                | ((uint32_t)buf[off + 3] << 24);
        off += 4;
        if ((size_t)stored_size > n - off) return false;
        Entry e;
        e.name = std::move(name);
        e.method = method;
        e.stored_size = stored_size;
        e.original_size = original_size;
        e.data.assign(buf.begin() + off, buf.begin() + off + stored_size);
        entries.push_back(std::move(e));
        off += stored_size;
    }
    if (off != n) return false;
    return true;
}

// ---------------------------------------------------------------- RLE decode
static bool decode_rle(const std::vector<char>& data, uint32_t original_size,
                       std::vector<char>& out) {
    out.clear();
    out.reserve(original_size > 4096 ? original_size : data.size());
    size_t pos = 0;
    size_t dec = 0;
    while (pos < data.size()) {
        uint8_t count = (uint8_t)data[pos];
        pos += 1;
        if (count == 0) return false;
        if (pos >= data.size()) return false;
        uint8_t byte = (uint8_t)data[pos];
        pos += 1;
        out.insert(out.end(), count, byte);
        dec += count;
    }
    return dec == original_size;
}

int main(int argc, char** argv) {
    if (argc != 3) {
        std::fprintf(stderr, "usage: %s <archive> <outdir>\n", argv[0]);
        return 1;
    }

    std::ifstream f(argv[1], std::ios::binary | std::ios::ate);
    if (!f) {
        std::fprintf(stderr, "cannot open archive '%s'\n", argv[1]);
        return 3;
    }
    std::streamsize size = f.tellg();
    if (size < 0) {
        std::fprintf(stderr, "cannot stat archive '%s'\n", argv[1]);
        return 3;
    }
    std::vector<char> buf((size_t)size);
    f.seekg(0, std::ios::beg);
    if (size > 0 && !f.read(buf.data(), size)) {
        std::fprintf(stderr, "cannot read archive '%s'\n", argv[1]);
        return 3;
    }

    std::vector<Entry> entries;
    if (!parse_archive(buf, entries)) {
        std::fprintf(stderr, "corrupt archive '%s'\n", argv[1]);
        return 3;
    }
    for (const Entry& e : entries) {
        if (!name_safe(e.name)) {
            std::fprintf(stderr, "unsafe entry name: '%s'\n", e.name.c_str());
            return 2;
        }
        if (e.method > 1) {
            std::fprintf(stderr, "unknown compression method %d\n", (int)e.method);
            return 3;
        }
    }
    for (size_t i = 0; i < entries.size(); ++i) {
        if (entries[i].method == 0 && entries[i].stored_size != entries[i].original_size) {
            std::fprintf(stderr, "stored size mismatch for '%s'\n", entries[i].name.c_str());
            return 3;
        }
        if (entries[i].method == 1) {
            std::vector<char> decoded;
            if (!decode_rle(entries[i].data, entries[i].original_size, decoded)) {
                std::fprintf(stderr, "invalid RLE data for '%s'\n", entries[i].name.c_str());
                return 3;
            }
            entries[i].data.swap(decoded);
        }
    }

    fs::path outdir = argv[2];
    fs::create_directories(outdir);
    for (const Entry& e : entries) {
        fs::path p = outdir / e.name;
        fs::create_directories(p.parent_path());
        std::ofstream out(p, std::ios::binary | std::ios::trunc);
        if (!out) {
            std::fprintf(stderr, "cannot write '%s'\n", p.string().c_str());
            return 3;
        }
        out.write(e.data.data(), e.data.size());
        if (!out) {
            std::fprintf(stderr, "write failed for '%s'\n", p.string().c_str());
            return 3;
        }
    }
    return 0;
}
